// Core Testing Fundamentals — Part 2 (q106–210)
window.QUIZ_BANK['core-testing'] = (window.QUIZ_BANK['core-testing']||[]).concat([
{id:106,topic:'core-testing',difficulty:'beginner',question:'What is a "test condition"?',options:['A hardware prerequisite for running tests','A testable aspect of a component derived from the test basis','The pass/fail status of a test case','A performance threshold'],answer:1,explanation:'A test condition is a specific item or event that can be tested, derived from the test basis (requirements, design, code).'},
{id:107,topic:'core-testing',difficulty:'beginner',question:'Which test level is closest to the end user and furthest from the code?',options:['Unit testing','Integration testing','System testing','Acceptance testing'],answer:3,explanation:'Acceptance testing is performed from the user\'s perspective to validate the system meets business needs; it is the highest and most user-centric test level.'},
{id:108,topic:'core-testing',difficulty:'beginner',question:'A test case that passes when expected to fail is known as:',options:['A false positive','An unexpected pass (or "untested" issue)','A flaky test','A smoke test'],answer:1,explanation:'An unexpected pass (sometimes called an "unexpected success") may indicate the test is incorrectly written, the defect was silently fixed, or the test environment is misconfigured.'},
{id:109,topic:'core-testing',difficulty:'beginner',question:'Which of the following describes "negative testing"?',options:['Testing that the system performs well under low load','Testing invalid, unexpected, or incorrect inputs to verify the system handles them gracefully','Testing that the system produces negative numbers correctly','Testing that logging and monitoring capture all events'],answer:1,explanation:'Negative testing deliberately submits invalid or unexpected inputs to verify the system rejects them properly and does not crash or produce incorrect output.'},
{id:110,topic:'core-testing',difficulty:'beginner',question:'What is a "test script"?',options:['A document summarising test results','A set of automated or manual instructions for executing a test case, including exact inputs and expected outputs','A log of test execution times','The test management tool configuration'],answer:1,explanation:'A test script provides step-by-step instructions for executing a test: the exact input data, navigation steps, and the expected outcome at each step.'},
{id:111,topic:'core-testing',difficulty:'beginner',question:'Which role is primarily responsible for defining the testing strategy in a project?',options:['Developer','Test manager / test lead','Business analyst','Product owner'],answer:1,explanation:'The test manager or test lead defines the overall testing strategy: approach, resources, schedule, tools, and risk coverage, which is captured in the test plan.'},
{id:112,topic:'core-testing',difficulty:'beginner',question:'What does "ISTQB" stand for?',options:['International Software Testing Qualification Board','Integrated Software Test Quality Bureau','International Standard for Testing and Quality Benchmarks','Internal Software Testing Quality Baseline'],answer:0,explanation:'ISTQB stands for International Software Testing Qualifications Board, the body that offers globally recognised software testing certifications.'},
{id:113,topic:'core-testing',difficulty:'beginner',question:'Which type of testing evaluates accessibility for users with disabilities?',options:['Security testing','Accessibility testing (a11y)','Load testing','Regression testing'],answer:1,explanation:'Accessibility testing (a11y) verifies that software is usable by people with visual, auditory, motor, or cognitive disabilities, typically against WCAG guidelines.'},
{id:114,topic:'core-testing',difficulty:'beginner',question:'Which of the following is a project risk in testing?',options:['The payment module may calculate totals incorrectly','The authentication system might be vulnerable to SQL injection','The test environment may not be available on schedule','The UI may not render correctly on older browsers'],answer:2,explanation:'Project risks affect the project management factors (schedule, resources, environment availability); product risks relate to potential failures of the software itself.'},
{id:115,topic:'core-testing',difficulty:'beginner',question:'What is "test data"?',options:['The list of all test cases','Data input values, files, or database content required to execute test cases','The results from automated test runs','The version control history of test scripts'],answer:1,explanation:'Test data is the specific set of input values, configurations, or database records required to execute test cases and produce measurable results.'},
{id:116,topic:'core-testing',difficulty:'beginner',question:'Which of the following is an example of a usability issue?',options:['The application crashes when uploading a file larger than 10 MB','The checkout button is labelled "Proceed" on mobile but "Confirm Purchase" on desktop','The API response time exceeds 3 seconds','User passwords are stored in plaintext'],answer:1,explanation:'Inconsistent labelling of the same action across platforms creates confusion — a usability issue related to consistency and clarity for users.'},
{id:117,topic:'core-testing',difficulty:'beginner',question:'In testing, what does "environment" refer to?',options:['The physical office location of testers','The combination of hardware, software, network configuration, and test data on which tests are run','The project management methodology','The collection of test cases'],answer:1,explanation:'A test environment comprises the complete technical configuration (hardware, OS, middleware, browser, database, network settings) required to execute tests.'},
{id:118,topic:'core-testing',difficulty:'beginner',question:'What is the purpose of regression testing after a bug fix?',options:['To design new test cases for the fixed functionality','To verify the fix works AND that existing features were not broken by the change','To rewrite the test plan','To close all open defects automatically'],answer:1,explanation:'Regression testing after a fix serves dual purposes: confirmation testing (verify the fix) and regression testing (verify no unintended side effects on other features).'},
{id:119,topic:'core-testing',difficulty:'beginner',question:'Which metric indicates what percentage of requirements have at least one test case covering them?',options:['Defect density','Requirements coverage','Test execution rate','Defect removal efficiency'],answer:1,explanation:'Requirements coverage = (requirements with at least one test case / total requirements) × 100; it measures how well the test suite addresses the specification.'},
{id:120,topic:'core-testing',difficulty:'beginner',question:'What is the "test closure" phase?',options:['The moment when the first test case is executed','The phase where testing activities are wrapped up: documenting lessons learned, archiving assets, and producing the test summary report','When the test environment is set up','When all defects are assigned to developers'],answer:1,explanation:'Test closure formalises the end of a test phase: completing remaining tasks, archiving test assets, capturing metrics, writing the test summary report, and recording lessons learned.'},
{id:121,topic:'core-testing',difficulty:'intermediate',question:'A developer runs unit tests achieving 80% statement coverage. What does this mean?',options:['80% of test cases passed','80% of executable statements were executed by at least one test','80% of requirements are tested','80% of branches were exercised'],answer:1,explanation:'Statement coverage measures the percentage of executable code statements exercised by the test suite; 80% means 1 in 5 statements was never executed.'},
{id:122,topic:'core-testing',difficulty:'intermediate',question:'Which testing technique is most appropriate when a system has multiple inputs each with two possible values (true/false)?',options:['State transition testing','Decision table testing','Boundary value analysis','Use case testing'],answer:1,explanation:'Decision tables systematically handle all combinations of boolean conditions; for N two-value conditions, a full table has 2^N rule columns.'},
{id:123,topic:'core-testing',difficulty:'intermediate',question:'Why is early defect detection (shift-left) economically beneficial?',options:['It removes the need for production monitoring','Defect fix cost grows exponentially the later a defect is found in the SDLC','It eliminates the need for regression testing','Early testing takes less total calendar time'],answer:1,explanation:'The IBM study and others confirm that fixing a defect in production costs 100× more than fixing it in requirements; early detection dramatically reduces rework cost.'},
{id:124,topic:'core-testing',difficulty:'intermediate',question:'Which document is used to formally report multiple test execution results and is typically reviewed by project stakeholders?',options:['Defect report','Test summary report','Test plan','Test case specification'],answer:1,explanation:'The test summary report consolidates results, metrics, quality risk assessment, and a recommendation for the project stakeholders at the end of a test phase.'},
{id:125,topic:'core-testing',difficulty:'intermediate',question:'In test management, what is the purpose of a "test charter" in exploratory testing?',options:['To define the overall test strategy for the project','To provide a mission or goal for a specific exploratory testing session','To assign test cases to testers','To list the entry criteria for the test phase'],answer:1,explanation:'A test charter scopes an exploratory session: it states what to explore, the target and approach, helping testers focus without being overly prescriptive.'},
{id:126,topic:'core-testing',difficulty:'intermediate',question:'How does "risk-based testing" prioritise test execution?',options:['By executing the easiest tests first to build confidence','By executing the tests with the highest likelihood × impact of failure first','By alphabetical order of test case IDs','By the order in which requirements were written'],answer:1,explanation:'Risk-based testing uses a risk matrix (likelihood × impact) to prioritise testing effort towards areas where failures would cause the most business harm.'},
{id:127,topic:'core-testing',difficulty:'intermediate',question:'What is the relationship between black-box and white-box testing approaches?',options:['Black-box can only be done manually; white-box must be automated','Black-box derives tests from requirements/specifications; white-box derives tests from internal code structure','White-box is always more thorough than black-box','They cannot be used in the same project'],answer:1,explanation:'Black-box ignores internals and tests behaviour against specs. White-box uses code knowledge to design tests for internal paths, branches, and conditions.'},
{id:128,topic:'core-testing',difficulty:'intermediate',question:'A test cycle is ending. 92 of 100 planned tests have been executed. 8 are blocked by an open critical defect. What is the appropriate action?',options:['Mark all 8 as passed because the environment is stable','Log the 8 as blocked and document the blocking defect in the test summary report','Cancel the test cycle and restart from scratch','Immediately escalate and close all open defects'],answer:1,explanation:'Blocked test cases should be documented as blocked with the reason; the test summary report should clearly identify the blocking defect and its impact on coverage.'},
{id:129,topic:'core-testing',difficulty:'intermediate',question:'Which agile ceremony is most closely related to test planning activities?',options:['Sprint review','Sprint retrospective','Sprint planning','Daily stand-up'],answer:2,explanation:'Sprint planning is where the team selects user stories and plans the work for the sprint — testers contribute by identifying test scenarios and acceptance criteria.'},
{id:130,topic:'core-testing',difficulty:'intermediate',question:'What does "ATDD" stand for and what is its primary benefit?',options:['Automated Test Driven Development — speeds up automation','Acceptance Test Driven Development — aligns the team on acceptance criteria before code is written','Advanced Test Design Documentation — improves test case quality','Automated Technical Design Documentation — removes manual specification'],answer:1,explanation:'ATDD (Acceptance Test Driven Development) involves writing acceptance tests collaboratively before development begins, ensuring shared understanding of "done" across developers, testers, and business stakeholders.'},
{id:131,topic:'core-testing',difficulty:'intermediate',question:'Which type of testing verifies that the system meets applicable legal, regulatory, or contractual requirements?',options:['Compliance / conformance testing','Ad-hoc testing','Exploratory testing','Usability testing'],answer:0,explanation:'Compliance testing confirms the system meets external standards, regulations (e.g., GDPR, PCI-DSS, HIPAA), or contractual obligations.'},
{id:132,topic:'core-testing',difficulty:'intermediate',question:'A tester finds a critical defect on the last day of the sprint. The defect has a workaround and fixing it requires significant refactoring. What is the recommended action?',options:['Force the developer to fix it immediately before the sprint ends','Log it with full details, agree on severity/priority with the team, and plan the fix in the backlog','Close it without logging because there is a workaround','Mark it as "deferred" and stop testing'],answer:1,explanation:'Defects should always be logged with full details regardless of timing. Severity, priority, and scheduling the fix are collaborative decisions involving the team and product owner.'},
{id:133,topic:'core-testing',difficulty:'intermediate',question:'In load testing, what is a "virtual user"?',options:['A test account on the production system','A simulated user generated by a load testing tool to represent concurrent usage','A tester executing manual scenarios','A developer account used for debug purposes'],answer:1,explanation:'Virtual users (VUs) are simulated users created by load testing tools (JMeter, k6, Gatling) to replicate concurrent usage patterns without requiring real users.'},
{id:134,topic:'core-testing',difficulty:'intermediate',question:'What is "test estimation" and which techniques are commonly used?',options:['Predicting how many defects will be found; uses statistical models only','Predicting effort, duration, and cost of testing; uses techniques like expert judgement, wideband delphi, and analogy-based estimation','Estimating the size of the application; uses function point analysis only','Scheduling the deployment date; uses the project Gantt chart'],answer:1,explanation:'Test estimation predicts testing effort and schedule; common techniques include expert judgement, analogy-based estimation, three-point estimation, and Wideband Delphi.'},
{id:135,topic:'core-testing',difficulty:'intermediate',question:'What is "orthogonal array testing" (OAT)?',options:['A form of white-box testing for orthogonal code paths','A statistical test design technique that provides even coverage of all parameter combinations with a minimal number of tests','A method for testing matrix operations','A framework for parallel test execution'],answer:1,explanation:'OAT uses mathematical orthogonal arrays to select a representative subset of all parameter combinations, providing balanced coverage with far fewer tests than full combinatorial testing.'},
{id:136,topic:'core-testing',difficulty:'intermediate',question:'Which of the following statements about exploratory testing is TRUE?',options:['It requires no skill and anyone can do it effectively','Experienced testers find more defects through exploratory testing than through purely scripted testing','Exploratory testing replaces all other testing types in agile','Exploratory testing produces no documentation'],answer:1,explanation:'Research and industry experience consistently show skilled exploratory testers find defects that scripted tests miss; experience and domain knowledge are key differentiators.'},
{id:137,topic:'core-testing',difficulty:'intermediate',question:'What is "test independence" and why is it beneficial?',options:['Each test case runs without dependencies on other tests; prevents cascading failures and makes debugging easier','All tests run in isolation on separate machines; reduces costs','Testers work independently from developers; reduces bias in defect finding','Test data is generated independently of the test cases'],answer:2,explanation:'Test independence means testers review and test work they did not produce themselves; this reduces confirmation bias and tends to find more defects than self-review.'},
{id:138,topic:'core-testing',difficulty:'intermediate',question:'When should a defect be classified as "deferred"?',options:['When the developer cannot reproduce it','When the tester has not verified it yet','When the team agrees it is a real defect but it will not be fixed in the current release','When the defect is a duplicate'],answer:2,explanation:'Deferred defects are confirmed valid but scheduled for a future release or sprint due to priority, risk, or resource constraints; they remain tracked in the defect log.'},
{id:139,topic:'core-testing',difficulty:'intermediate',question:'What is "boundary value analysis" specifically designed to detect?',options:['Logic errors in conditional statements','Off-by-one errors and input handling at the edges of valid ranges','Performance bottlenecks at extreme loads','Integration failures between modules'],answer:1,explanation:'BVA targets the common developer error of off-by-one: using > instead of >=, or iterating one step too many/few, which manifests at boundary values.'},
{id:140,topic:'core-testing',difficulty:'intermediate',question:'In agile, "three amigos" refers to:',options:['Three rounds of testing before each release','A collaboration session between a business analyst (or product owner), developer, and tester to clarify a user story before development','Three automated test types: unit, integration, and UI','Three stakeholders who sign off on the test plan'],answer:1,explanation:'Three amigos is a collaboration technique where the product owner/BA, developer, and tester discuss a story together to reach shared understanding, surface assumptions, and define acceptance criteria.'},
{id:141,topic:'core-testing',difficulty:'advanced',question:'What does "mutation score" measure in mutation testing?',options:['The percentage of source lines modified','The ratio of killed mutants to total non-equivalent mutants','The number of mutants generated per test case','The complexity of mutant operators applied'],answer:1,explanation:'Mutation score = (killed mutants / (total mutants − equivalent mutants)) × 100. It measures the effectiveness of the test suite at detecting injected faults.'},
{id:142,topic:'core-testing',difficulty:'advanced',question:'Which of the following is an example of a first-order mutation operator?',options:['Inserting a complete function into the code','Changing a relational operator (e.g., < to <=) in a single location','Replacing an entire class with a mock','Swapping two complete methods'],answer:1,explanation:'First-order mutations apply a single syntactic change (e.g., swapping an operator, replacing a constant) to create one mutant; higher-order mutations apply multiple changes.'},
{id:143,topic:'core-testing',difficulty:'advanced',question:'What is the Automation Test Pyramid and why is it important?',options:['A diagram showing the hierarchy of test management roles','A model proposing many unit tests at the base, fewer integration tests in the middle, and few UI/E2E tests at the top to optimise speed, reliability, and cost','A framework for organising manual test cases','A chart of defect severity distribution'],answer:1,explanation:'The Test Pyramid (Mike Cohn) advocates heavy unit testing (fast, cheap) at the base, moderate integration/API tests in the middle, and minimal slow/expensive E2E UI tests at the top for an efficient, reliable suite.'},
{id:144,topic:'core-testing',difficulty:'advanced',question:'Why are flaky tests a critical problem in CI/CD pipelines?',options:['They run too quickly and skip code paths','They produce inconsistent results (sometimes pass, sometimes fail without code changes), eroding trust in the test suite and forcing teams to ignore failures','They consume too much memory','They cannot be run in parallel'],answer:1,explanation:'Flaky tests undermine confidence in the CI pipeline; teams begin ignoring red builds, masking real failures and defeating the purpose of automated testing.'},
{id:145,topic:'core-testing',difficulty:'advanced',question:'In the context of GDPR-compliant test data management, which practice is most appropriate when using production data for testing?',options:['Use production data as-is for maximum realism','Anonymise or pseudonymise personal data before using it in test environments','Encrypt test environments to protect production data','Only allow senior testers to access production test data'],answer:1,explanation:'GDPR and data protection regulations require that personal data be protected in test environments; data masking, anonymisation, or synthetic data generation are the compliant approaches.'},
{id:146,topic:'core-testing',difficulty:'advanced',question:'Which characteristic makes a test automation architecture maintainable long-term?',options:['Using hard-coded test data and absolute XPath locators','Separating test logic from test data and using a page object model (POM) or similar abstraction layer','Writing all tests in a single flat file','Using the latest GUI testing tools regardless of project need'],answer:1,explanation:'Separation of concerns (page objects, data-driven testing) isolates UI changes to one place, dramatically reducing maintenance effort when the application changes.'},
{id:147,topic:'core-testing',difficulty:'advanced',question:'What is "model-based testing" (MBT)?',options:['Testing software that models physical processes','An approach where tests are automatically generated from a formal model of the system\'s expected behaviour','A testing approach using UML class diagrams only','Generating performance models from production logs'],answer:1,explanation:'MBT uses formal models (state machines, flow graphs) to automatically generate test cases, improving coverage and reducing manual test design effort.'},
{id:148,topic:'core-testing',difficulty:'advanced',question:'Which approach best addresses the "oracle problem" in automated testing?',options:['Using random inputs with no expected output','Using automated oracles: expected outputs derived from specifications, reference implementations, or metamorphic relations','Relying solely on crash detection','Requiring all tests to have manual verification steps'],answer:1,explanation:'The oracle problem (how do we know the correct output?) is addressed by defining automated oracles from specifications, mathematical properties (metamorphic testing), or comparing to reference implementations.'},
{id:149,topic:'core-testing',difficulty:'advanced',question:'What is "property-based testing"?',options:['Testing the CSS properties of a web application','A technique where the tester defines general properties that should hold for all inputs, and a tool generates random inputs to try to falsify those properties','Testing database properties like NOT NULL constraints','Testing configuration properties in CI/CD pipelines'],answer:1,explanation:'Property-based testing (e.g., QuickCheck, Hypothesis) defines invariants and lets the tool generate diverse inputs to find edge cases that violate those properties.'},
{id:150,topic:'core-testing',difficulty:'advanced',question:'What distinguishes "fault injection testing" from regular functional testing?',options:['Fault injection deliberately introduces faults (hardware errors, network failures, corrupted data) into the system to verify it handles them gracefully','Fault injection is purely manual; functional testing can be automated','Fault injection measures code coverage; functional testing measures requirements coverage','There is no meaningful distinction'],answer:0,explanation:'Fault injection (used in reliability and security testing) deliberately triggers error conditions — corrupted packets, memory errors, hardware faults — to verify resilience and error handling.'},
{id:151,topic:'core-testing',difficulty:'beginner',question:'What is the difference between a defect and a failure?',options:['They are the same thing','A defect is a flaw in the code; a failure is the observable incorrect behaviour when the defect is executed','A failure is in the requirements; a defect is in the code','A defect is always critical; a failure is always low severity'],answer:1,explanation:'ISTQB distinguishes: a defect (bug, fault) is the root cause in the work product; a failure is the observable incorrect system behaviour when the defect is triggered at runtime.'},
{id:152,topic:'core-testing',difficulty:'beginner',question:'Which of the following is NOT a type of non-functional testing?',options:['Performance testing','Security testing','Regression testing','Accessibility testing'],answer:2,explanation:'Regression testing is a type of functional testing (verifying that existing features still work); performance, security, and accessibility are all non-functional testing types.'},
{id:153,topic:'core-testing',difficulty:'beginner',question:'What does "test basis" NOT include?',options:['Requirements specification','System architecture documents','Source code (for white-box test design)','The tester\'s salary information'],answer:3,explanation:'The test basis includes all artefacts used to derive test conditions: requirements, design specs, user stories, code — but not administrative HR information.'},
{id:154,topic:'core-testing',difficulty:'beginner',question:'A software product is being tested to verify it works correctly on both Windows and macOS. What type of testing is this?',options:['Load testing','Compatibility testing','Stress testing','Security testing'],answer:1,explanation:'Cross-platform testing is a form of compatibility testing, verifying the software functions correctly across specified OS, browser, or device configurations.'},
{id:155,topic:'core-testing',difficulty:'beginner',question:'What is the primary purpose of test automation?',options:['To completely eliminate manual testing','To execute repetitive, deterministic tests faster and more reliably than manual execution','To generate test requirements automatically','To replace the test manager role'],answer:1,explanation:'Test automation speeds up repetitive regression and smoke testing, frees testers for exploratory work, and enables fast CI/CD feedback — not to replace all manual testing.'},
{id:156,topic:'core-testing',difficulty:'beginner',question:'Which of the following best describes "end-to-end testing"?',options:['Testing a single function in isolation','Testing the complete workflow from start to finish across all system components, simulating real user journeys','Testing only the database transactions','Testing the network layer only'],answer:1,explanation:'End-to-end (E2E) tests validate complete business workflows across all layers (UI, API, database, integrations), simulating how real users interact with the system.'},
{id:157,topic:'core-testing',difficulty:'beginner',question:'In test reporting, what does "pass rate" indicate?',options:['The percentage of requirements covered by tests','The percentage of executed test cases that resulted in a pass outcome','The number of defects found per test case','The speed of test execution'],answer:1,explanation:'Pass rate = (passed test cases / total executed test cases) × 100. It is a key KPI for assessing the stability of the build under test.'},
{id:158,topic:'core-testing',difficulty:'beginner',question:'Which type of testing ensures the system is free of vulnerabilities like SQL injection and XSS?',options:['Load testing','Security testing','Usability testing','Regression testing'],answer:1,explanation:'Security testing identifies vulnerabilities (SQL injection, XSS, authentication bypass, etc.) to ensure the system protects data and resists malicious attacks.'},
{id:159,topic:'core-testing',difficulty:'beginner',question:'What does "retest" mean in a defect lifecycle context?',options:['Running the complete regression suite again','Re-executing the specific test case(s) that originally found a defect, after a fix has been applied','Restarting the test environment','Redesigning the test cases for a module'],answer:1,explanation:'Retesting (confirmation testing) specifically re-executes the failing tests from a reported defect after the developer has applied a fix, to verify resolution.'},
{id:160,topic:'core-testing',difficulty:'beginner',question:'What information must every test case contain at minimum?',options:['The name of the tester only','Test ID, title, preconditions, steps, expected result, and actual result field','Developer contact details','Source code reference'],answer:1,explanation:'A complete test case requires an ID, description/title, preconditions, execution steps, expected result, and a field to record the actual result during execution.'},
{id:161,topic:'core-testing',difficulty:'intermediate',question:'What is "pairwise testing" also known as?',options:['All-pairs testing or 2-way combinatorial testing','Dual coverage testing','Two-path white-box testing','Binary boundary testing'],answer:0,explanation:'Pairwise (all-pairs) testing is a combinatorial technique ensuring that every pair of parameter values appears together at least once; it typically provides 60-90% fault detection with far fewer tests than full combinations.'},
{id:162,topic:'core-testing',difficulty:'intermediate',question:'A banking application has a discount function that gives 5% for balances $1000-$4999, 10% for $5000-$9999, and 15% for $10000+. How many equivalence classes exist?',options:['2','3','4','5'],answer:2,explanation:'There are 4 equivalence classes: < $1000 (no discount), $1000-$4999 (5%), $5000-$9999 (10%), ≥ $10000 (15%).'},
{id:163,topic:'core-testing',difficulty:'intermediate',question:'Which test management tool feature allows linking defects directly to test cases?',options:['Test execution scheduler','Defect-to-test traceability / bidirectional traceability','Code coverage analyser','Load test runner'],answer:1,explanation:'Bidirectional traceability in test management tools (Jira, Zephyr, TestRail) links defects to the test cases that found them and to the requirements they cover.'},
{id:164,topic:'core-testing',difficulty:'intermediate',question:'What is "test-driven development" (TDD)?',options:['Writing all tests after implementation is complete','Writing a failing test first, then writing minimum code to make it pass, then refactoring','Developing a test automation framework before writing application code','Driving development schedules from test metrics'],answer:1,explanation:'TDD follows a red-green-refactor cycle: write a failing unit test → write minimal code to pass it → refactor. It produces high unit test coverage by design.'},
{id:165,topic:'core-testing',difficulty:'intermediate',question:'In which scenario is exploratory testing MOST valuable?',options:['Highly regulated systems with extensive pre-defined test scripts','New features with vague requirements, or when investigating recently discovered defect clusters','Regression testing of stable legacy systems','Performance testing of high-traffic APIs'],answer:1,explanation:'Exploratory testing excels where scripted tests are insufficient: new features, vague requirements, complex user interactions, or when probing around defect clusters.'},
{id:166,topic:'core-testing',difficulty:'intermediate',question:'What does "test infrastructure" include?',options:['Only the hardware servers','Test environments, test data, test tools, version control, CI server, and any supporting services needed for test execution','The project management office','The test team organizational chart'],answer:1,explanation:'Test infrastructure encompasses all the supporting components needed to run tests: environments, test data stores, automation tools, CI/CD pipelines, and version-controlled test repositories.'},
{id:167,topic:'core-testing',difficulty:'intermediate',question:'Which testing type most directly measures user satisfaction with the product?',options:['Alpha testing','Usability testing','Unit testing','Regression testing'],answer:1,explanation:'Usability testing collects direct feedback on the user experience — ease of use, learnability, and satisfaction — measuring whether users can achieve their goals efficiently.'},
{id:168,topic:'core-testing',difficulty:'intermediate',question:'What is "configuration testing"?',options:['Testing that the version control configuration is correct','Verifying the software performs correctly under different hardware and software configuration combinations','Testing application logging configuration','Testing that CI/CD pipeline configurations are valid'],answer:1,explanation:'Configuration testing verifies that the software works under specified hardware, OS, browser, middleware, and network configuration combinations.'},
{id:169,topic:'core-testing',difficulty:'intermediate',question:'Which of the following BEST describes "regression testing scope"?',options:['Always the full test suite run after every change','A risk-based subset of tests covering areas likely impacted by recent changes, plus core functionality','Only the tests related to the changed feature','All tests tagged as high-priority'],answer:1,explanation:'Risk-based regression selects tests based on change impact analysis and core feature criticality, balancing thoroughness with the practical time constraints of each release cycle.'},
{id:170,topic:'core-testing',difficulty:'intermediate',question:'What is "code-based test design" another name for?',options:['Black-box testing','White-box / structural testing','Exploratory testing','Experience-based testing'],answer:1,explanation:'White-box (structural) testing derives test cases from the internal structure of the code — statements, branches, paths, conditions — making it synonymous with code-based test design.'},
{id:171,topic:'core-testing',difficulty:'advanced',question:'In ISO/IEC 25010, which sub-characteristic of "Reliability" measures the ability of software to continue operating when components fail?',options:['Maturity','Fault tolerance','Recoverability','Availability'],answer:1,explanation:'Fault tolerance is the sub-characteristic measuring how well the software maintains its required functions when hardware or software faults occur.'},
{id:172,topic:'core-testing',difficulty:'advanced',question:'What is "chaos engineering" and how does it relate to testing?',options:['Randomly deleting code to find bugs','The discipline of experimenting on a production system by deliberately injecting failures to build confidence in the system\'s resilience','An unstructured form of exploratory testing','A method for generating random test data'],answer:1,explanation:'Chaos engineering (pioneered by Netflix\'s Chaos Monkey) proactively injects failures in production to validate that distributed systems can withstand unexpected disruptions gracefully.'},
{id:173,topic:'core-testing',difficulty:'advanced',question:'What is the key difference between "verification" and "validation" in V&V?',options:['Verification is done at runtime; validation is static','Verification checks correctness against specifications (are we building it right?); validation checks fitness for purpose against user needs (are we building the right thing?)','Verification is done by developers; validation is done by testers only','Validation precedes verification in the SDLC'],answer:1,explanation:'V&V: Verification = conformance to specification (static or dynamic); Validation = fitness for purpose confirmed with users (typically dynamic acceptance testing).'},
{id:174,topic:'core-testing',difficulty:'advanced',question:'Which test technique uses the syntax: "Given [context], When [action], Then [expected outcome]"?',options:['Use case testing','BDD (Behaviour Driven Development) scenario syntax','State transition format','Decision table format'],answer:1,explanation:'The Gherkin Given/When/Then syntax is the foundation of BDD scenarios, creating executable specifications that bridge business language and automated test code.'},
{id:175,topic:'core-testing',difficulty:'advanced',question:'A system has 5 independent boolean conditions. How many rules (columns) does a full decision table have?',options:['5','10','16','32'],answer:3,explanation:'A full decision table for N independent binary conditions has 2^N rules (columns). For 5 conditions: 2^5 = 32 columns.'},
{id:176,topic:'core-testing',difficulty:'advanced',question:'What does "risk-based test prioritisation" specifically NOT do?',options:['Rank test cases by business impact of failure','Eliminate the need to test low-risk areas entirely','Ensure highest-risk areas are tested first','Optimise test execution order'],answer:1,explanation:'Risk-based prioritisation does not eliminate low-risk testing — it still requires those areas to be tested eventually; it only changes execution order and resource allocation.'},
{id:177,topic:'core-testing',difficulty:'advanced',question:'What does "continuous testing" mean in a DevOps context?',options:['Running tests 24/7 on a dedicated machine','Testing at every stage of the software delivery pipeline, from code commit to production, providing immediate risk feedback','Testing continuously without pausing for defect fixes','Running the same tests continuously in a loop'],answer:1,explanation:'Continuous testing embeds automated testing at every pipeline stage — unit, integration, security, performance, acceptance — to give teams instant quality feedback throughout the delivery process.'},
{id:178,topic:'core-testing',difficulty:'advanced',question:'Which Agile testing quadrant contains performance, security, and "ility" tests that critique the product from a technical perspective?',options:['Q1','Q2','Q3','Q4'],answer:3,explanation:'Agile Testing Quadrant Q4 (Technology-facing, Critique Product) includes performance, load, security, and "-ility" tests that evaluate technical quality from outside the application.'},
{id:179,topic:'core-testing',difficulty:'advanced',question:'What is the purpose of "test impact analysis"?',options:['Measuring the business impact of test automation investment','Identifying which existing tests need to be re-run based on recent code changes, minimising regression suite execution time','Analysing the root cause of test failures','Measuring the impact of adding more testers to a project'],answer:1,explanation:'Test impact analysis maps code changes to affected tests, allowing CI pipelines to run only the relevant subset of the regression suite rather than the full suite on every commit.'},
{id:180,topic:'core-testing',difficulty:'advanced',question:'What is "specification by example" (SBE)?',options:['Writing requirements with code examples','A collaborative requirements technique that uses concrete examples to specify system behaviour, forming the basis for automated acceptance tests','Documenting all test cases with sample data','Providing annotated API documentation'],answer:1,explanation:'SBE (a key BDD/ATDD practice) uses concrete, realistic examples of expected behaviour to drive requirements discussions and directly derive executable acceptance tests.'},
{id:181,topic:'core-testing',difficulty:'beginner',question:'What is "ad-hoc testing"?',options:['Testing that follows a strict predefined plan','Informal, unstructured testing without formal test cases, relying on the tester\'s intuition','Testing performed in an ad-hoc (temporary) environment','Automated smoke testing'],answer:1,explanation:'Ad-hoc testing is performed without formal test cases or process; it relies on the tester\'s knowledge and intuition to find defects.'},
{id:182,topic:'core-testing',difficulty:'beginner',question:'Which of the following describes "positive testing"?',options:['Testing that the system rejects invalid inputs','Verifying that the system produces correct results for valid inputs','Testing only the positive (successful) user flows','Running tests when team morale is high'],answer:1,explanation:'Positive testing verifies that the system behaves correctly for valid, expected inputs and user actions — confirming the "happy path" works.'},
{id:183,topic:'core-testing',difficulty:'beginner',question:'What does "reproducibility" mean for a defect?',options:['The defect exists in multiple applications','The ability to consistently trigger the defect by following the reproduction steps','The defect occurs randomly and cannot be recreated','The defect is reproduced in every test environment'],answer:1,explanation:'A reproducible defect can be consistently triggered by following the documented steps to reproduce; reproducibility is critical for developers to locate and fix the fault.'},
{id:184,topic:'core-testing',difficulty:'beginner',question:'Which test phase typically follows system testing in the traditional SDLC?',options:['Unit testing','Integration testing','Acceptance testing','Regression testing'],answer:2,explanation:'In the traditional V-model, acceptance testing follows system testing; it validates the complete system against business requirements with end-user involvement.'},
{id:185,topic:'core-testing',difficulty:'beginner',question:'A tester logs a defect but the developer cannot reproduce it. What should the tester do first?',options:['Close the defect immediately','Provide detailed reproduction steps, test data, environment details, screenshots/logs, and re-demonstrate if possible','Escalate to the project manager immediately','Mark it as a "known issue" and move on'],answer:1,explanation:'The tester should enrich the defect report with precise reproduction steps, environment configuration, test data, and supporting evidence (screenshots, logs) to help the developer reproduce it.'},
{id:186,topic:'core-testing',difficulty:'beginner',question:'Which of the following is the correct order of the defect lifecycle?',options:['New → Assigned → Fixed → Retest → Closed','New → Fixed → Assigned → Retest → Closed','New → Closed → Assigned → Retest → Fixed','New → Retest → Assigned → Fixed → Closed'],answer:0,explanation:'The typical defect lifecycle: New (logged) → Assigned (to developer) → Fixed (developer resolves) → Retest (QA verifies) → Closed (verified fixed) or Reopened.'},
{id:187,topic:'core-testing',difficulty:'beginner',question:'What is "test estimation technique" called when multiple experts independently estimate, share estimates, discuss differences, and re-estimate until consensus is reached?',options:['Three-point estimation','Planning poker','Wideband Delphi','Function point analysis'],answer:2,explanation:'Wideband Delphi is a structured technique where independent expert estimates are shared anonymously, differences are discussed, and rounds continue until consensus emerges.'},
{id:188,topic:'core-testing',difficulty:'beginner',question:'What does "traceability" in testing ensure?',options:['Test cases are written in a traceable format','Every test case can be traced back to a requirement, and every requirement is covered by at least one test case','Defects are tracked in a version control system','Test execution logs are retained for audit'],answer:1,explanation:'Traceability creates bidirectional links between requirements and tests, ensuring complete coverage and enabling impact analysis when requirements change.'},
{id:189,topic:'core-testing',difficulty:'beginner',question:'What is "test documentation"?',options:['Only the final test summary report','All documents created during testing: test plan, test cases, test scripts, test logs, defect reports, and summary reports','The user manual for the test tools','Version control configuration files'],answer:1,explanation:'Test documentation encompasses all artefacts produced throughout the testing process: plans, designs, test cases, logs, defect reports, and summaries.'},
{id:190,topic:'core-testing',difficulty:'beginner',question:'Which type of testing ensures individual lines of code are executed during testing?',options:['Branch coverage testing','Statement coverage testing','Path coverage testing','Condition coverage testing'],answer:1,explanation:'Statement coverage measures whether every executable line (statement) in the source code has been executed by at least one test case.'},
{id:191,topic:'core-testing',difficulty:'intermediate',question:'A login module receives 350 defects out of 500 total defects found across the entire application. What testing principle does this exemplify?',options:['Pesticide paradox','Exhaustive testing is impossible','Defect clustering','Absence of errors fallacy'],answer:2,explanation:'Defect clustering (Pareto/80-20) principle: a small number of modules (here the login module) contain a disproportionately high percentage of all defects.'},
{id:192,topic:'core-testing',difficulty:'intermediate',question:'Which of the following best describes "API testing"?',options:['Testing the graphical user interface of web applications','Testing application programming interfaces directly, verifying request/response correctness, error handling, and performance without UI interaction','Testing the source code of API implementations','Testing network infrastructure for API servers'],answer:1,explanation:'API testing validates REST, SOAP, or GraphQL interfaces directly — request structure, response codes, payloads, authentication, and performance — bypassing the UI layer.'},
{id:193,topic:'core-testing',difficulty:'intermediate',question:'In a CI/CD pipeline, which test type provides the fastest feedback on individual code changes?',options:['End-to-end UI tests','Manual exploratory testing','Unit tests','System integration tests'],answer:2,explanation:'Unit tests run in milliseconds, provide immediate feedback on individual function/method changes, and are run on every commit — making them the fastest feedback mechanism in CI.'},
{id:194,topic:'core-testing',difficulty:'intermediate',question:'What is "pair testing"?',options:['Using BVA and EP together','Two people (often a tester and developer, or two testers) working together at one workstation to test the same feature simultaneously','Testing the same feature with two different test tools','Running tests in pairs to reduce execution time'],answer:1,explanation:'Pair testing is a collaborative approach where two people work at one computer — one operating (driver) and one observing/thinking (navigator) — combining skills to find more defects.'},
{id:195,topic:'core-testing',difficulty:'intermediate',question:'What does "WCAG" stand for, and which testing type does it guide?',options:['Web Content Accessibility Guidelines — Accessibility testing','Web Code Analysis Guidelines — Static code testing','Web Compatibility Assessment Group — Cross-browser testing','Wide Coverage Automation Guide — Regression automation'],answer:0,explanation:'WCAG (Web Content Accessibility Guidelines) from W3C defines success criteria for web accessibility; conformance testing validates compliance with WCAG 2.1/2.2 levels A, AA, and AAA.'},
{id:196,topic:'core-testing',difficulty:'intermediate',question:'What is "test data management" (TDM)?',options:['Storing test case documents in a database','The processes and practices for creating, provisioning, maintaining, and cleaning test data to support test execution needs','Managing the test team\'s calendar and resource allocation','Configuring the test environment databases'],answer:1,explanation:'TDM covers the full lifecycle of test data: profiling production data, creating/masking synthetic data, provisioning data to environments, and cleaning up post-test.'},
{id:197,topic:'core-testing',difficulty:'intermediate',question:'Which of the following is a benefit of static testing over dynamic testing?',options:['It finds runtime performance issues','It can detect defects before the software is executable, when fix costs are lowest','It eliminates the need for any dynamic testing','It provides user acceptance validation'],answer:1,explanation:'Static testing (reviews, inspections, static analysis) finds defects in requirements, designs, and code before execution — at the stage when fixes are cheapest.'},
{id:198,topic:'core-testing',difficulty:'intermediate',question:'What does "test isolation" mean in unit testing?',options:['Running unit tests in a separate CI environment','Ensuring each unit test tests only one unit of code, using mocks/stubs to replace dependencies','Preventing testers from communicating during testing','Using isolated test data for each tester'],answer:1,explanation:'Test isolation means each unit test targets exactly one unit (class/function) and replaces all external dependencies (DB, services, files) with test doubles (mocks/stubs) to eliminate external interference.'},
{id:199,topic:'core-testing',difficulty:'intermediate',question:'In Agile testing, what is the purpose of "Definition of Ready" (DoR)?',options:['Defines when a sprint is complete','Defines the conditions a user story must meet before it can be brought into a sprint for development','Defines the minimum test case count per story','Defines when to deploy to production'],answer:1,explanation:'DoR establishes acceptance criteria that a user story must meet (e.g., clear acceptance criteria, estimated, no unresolved dependencies) before the team can commit to developing it in a sprint.'},
{id:200,topic:'core-testing',difficulty:'intermediate',question:'What is "static code analysis"?',options:['Manually reading through source code during code reviews','Automated inspection of source code without execution using tools (e.g., SonarQube, ESLint) to detect code quality issues, bugs, and security vulnerabilities','Running the application with monitoring enabled','Testing the database schema structure'],answer:1,explanation:'Static code analysis tools automatically scan source code to detect bugs, code smells, security vulnerabilities, and style violations without running the program.'},
{id:201,topic:'core-testing',difficulty:'advanced',question:'What is the primary distinction between "system testing" and "component testing"?',options:['Component testing uses black-box techniques; system testing uses white-box techniques','Component testing validates individual units in isolation; system testing validates the entire integrated system against end-to-end requirements','Component testing is done by developers; system testing is always done by QA','There is no distinction — they refer to the same level'],answer:1,explanation:'Component (unit) testing validates individual pieces of code in isolation. System testing validates the complete, integrated system from an end-user perspective against functional and non-functional requirements.'},
{id:202,topic:'core-testing',difficulty:'advanced',question:'Which principle from ISTQB states that the absence of defects does not mean the software is fit for use?',options:['Exhaustive testing is impossible','Defects cluster together','The absence-of-errors fallacy','Early testing saves cost'],answer:2,explanation:'The absence-of-errors fallacy recognises that a thoroughly tested, defect-free product can still fail to satisfy user needs if it was built to the wrong specification.'},
{id:203,topic:'core-testing',difficulty:'advanced',question:'What is "acceptance test-driven development" (ATDD) and how does it differ from TDD?',options:['ATDD is identical to TDD but uses different tools','ATDD drives design from business acceptance criteria defined before development; TDD drives design from unit-level technical test cases','ATDD is only applicable to agile projects; TDD is for waterfall','ATDD focuses on automation; TDD is always manual'],answer:1,explanation:'ATDD uses high-level business acceptance tests (Given/When/Then) to drive development from the outside in. TDD uses low-level unit tests to drive design from the inside out.'},
{id:204,topic:'core-testing',difficulty:'advanced',question:'In testing, what is a "test harness"?',options:['The physical test environment hardware','A collection of software and test data configured for test execution, including test drivers, stubs, and the framework that runs and reports tests','A security testing toolkit','The user interface for the test management tool'],answer:1,explanation:'A test harness is the complete environment (framework, drivers, stubs, test data, configuration) required to execute automated tests against the system under test.'},
{id:205,topic:'core-testing',difficulty:'advanced',question:'Which phenomenon describes where bugs that are not fixed continue to degrade the software quality over time as other code is added around them?',options:['Defect clustering','Technical debt accumulation','Broken windows theory applied to software quality','Regression creep'],answer:2,explanation:'The "broken windows" theory (applied to software by the Pragmatic Programmers) states that unfixed bugs signal a "culture of carelessness" and encourage further degradation of code quality.'},
{id:206,topic:'core-testing',difficulty:'advanced',question:'What is a key challenge in testing microservices architectures compared to monolithic applications?',options:['Microservices are easier to test because each service is small','The large number of independently deployable services creates complex integration and contract testing challenges','Microservices cannot be unit tested','Microservices always require more manual testing'],answer:1,explanation:'Microservices introduce contract testing challenges (verifying service interfaces), complex integration scenarios, distributed tracing difficulties, and the need for consumer-driven contract tests (e.g., Pact).'},
{id:207,topic:'core-testing',difficulty:'advanced',question:'What is "consumer-driven contract testing"?',options:['Testing that the consumer (client) writes test cases for the provider (server)','A technique where the consumer defines the expectations from a provider\'s API as a contract, and the provider verifies it can fulfil that contract, enabling independent deployment','Testing that customer requirements are fully documented','Load testing of API consumers'],answer:1,explanation:'Consumer-driven contract testing (tools: Pact) lets service consumers publish their expectations; providers run verification tests against those contracts, enabling microservices to be deployed independently without integration test environments.'},
{id:208,topic:'core-testing',difficulty:'advanced',question:'Which metric specifically measures the percentage of requirements covered by automated tests?',options:['Automation pass rate','Requirements automation coverage','Defect density','Mean time to detect'],answer:1,explanation:'Requirements automation coverage tracks what fraction of requirements have at least one automated test case, indicating the automated safety net\'s breadth.'},
{id:209,topic:'core-testing',difficulty:'advanced',question:'What is "service virtualisation" in testing?',options:['Deploying test services to virtual machines only','Simulating the behaviour of unavailable, costly, or incomplete dependent services (APIs, databases, mainframes) to enable testing without those real components','A tool for managing virtual test environments','Creating virtual test users for load testing'],answer:1,explanation:'Service virtualisation creates simulation of real services (e.g., payment gateways, legacy systems) that behave as specified but without the cost, access restrictions, or instability of the real component.'},
{id:210,topic:'core-testing',difficulty:'advanced',question:'In a CI/CD pipeline, "test gates" (quality gates) serve what purpose?',options:['Physical security doors in the test lab','Automated checks that block promotion to the next pipeline stage if quality thresholds (e.g., test pass rate, code coverage, zero critical defects) are not met','Manual sign-off forms between pipeline stages','Load balancers for distributing test execution'],answer:1,explanation:'Quality gates are automated pipeline checkpoints that enforce quality thresholds — if coverage < 80% or critical tests fail, the build is blocked from progressing to staging/production.'}
]);
